import{z as o,x as s,o as A,c as p,q as i,j as n,D as a,d as B,s as r,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"监控应用：欺骗检测","description":"","frontmatter":{"title":"监控应用：欺骗检测","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/xai-deception-monitoring.md","filePath":"llm/xai-deception-monitoring.md","lastUpdated":1791413859000}'),d={name:"llm/xai-deception-monitoring.md"};function D(F,E,m,c,C,h){const t=s("Mermaid");return A(),p("div",null,[E[2]||(E[2]=i('<h1 id="监控应用-欺骗检测" tabindex="-1">监控应用：欺骗检测 <a class="header-anchor" href="#监控应用-欺骗检测" aria-label="Permalink to &quot;监控应用：欺骗检测&quot;">​</a></h1><div class="epigraph"><p>行为可以表演，表征要参与执行；监控押注的是后者比前者更难藏——押注，不是定理。</p><footer>—— 据 Zou et al., 2023 与 Lindsey et al., 2025 的监控口径整理</footer></div><p><a href="/llm/xai-representation-engineering">上一课</a>给概念装上了坐标：读得出内部读数，写得进表征。本课把读数接进运营：在线监控激活，检测欺骗。先把语义钉住：<a href="/llm/specification-gaming">规约博弈课</a>把对齐失效分三格——规约错误、目标误泛化、欺骗性对齐；监控的主目标是第三格，模型在训练时表现对齐，是为了部署后做别的。行为评测只看输出，而欺骗的定义恰恰是输出与内部目标脱钩——这是本课存在的理由。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>为什么行为信号不够。第一，欺骗可以只在关键场合出现，行为评测的采样大概率错过。第二，思维链可以编造：Anthropic 2025 年的生物学论文里有个著名案例——模型在内幕交易的情境下隐瞒了动机，思维链看起来无辜，追踪其内部计算却显示它「知道」自己在做什么。第三，后门类问题里行为与触发条件绑定，正常流量上永远看不到背叛。</p><p><span class="marginnote">「探针」是什么：一种在模型内部激活上训练的简单分类器（常是线性模型），输入是某一层的激活向量，输出一个读数（比如「这段计算里欺骗方向激活了多强」）。类比：不看考卷上的答案（输出文本），而是在「思考过程」上装一个传感器。它便宜到可以每个请求都测一次，这是行为评测做不到的。</span></p><p>监控的问题化于是是系统性的：离线怎么建欺骗的内部坐标（上一课的读写）；在线怎么打分、什么阈值；告警之后谁接。工程上真正的约束不是检测率，是<strong>误报率</strong>：监控长年在全部流量上跑，阈值定错，第一天就被人审弃用。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>分层架构。</strong> 全流量上跑轻量读数——线性探针或<a href="/llm/xai-feature-validation">验证过的</a>欺骗特征读数，便宜、每请求可算；读数可疑的流量进重分析——更宽的字典读数、多探针投票、必要时抽到离线做归因图深查。分层把预算花在尾部，而不是把昂贵工具平摊到每个请求。</p><p><strong>告警带证据。</strong> 一条合格的告警不是裸分数，而是三件套：读数、触发样本的激活证据、该坐标的转向效应记录。人审看的是证据链，不是置信度。</p><p><strong>阈值由运营倒推。</strong> 先定每天可人审的告警条数，再按流量规模反解误报率上限，最后回到坐标侧调判别面或加投票——顺序反了的监控团队，上线一周后告警就没人看了。</p><p><span class="marginnote">常见误区：「阈值定在验证集准确率最高的点」。监控面对的流量极不平衡——真欺骗可能万中无一，一个「准确率 99.9%」的阈值可能意味着满屏误报、真样本淹没在里面。正确顺序是从运营倒推：每天能审 50 条，就按流量反解出误报率上限，再回头要求读数器达到那个精度。</span></p>',12)),(A(),n(l,null,{default:a(()=>[r(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E7%BA%BF%E4%B8%8A%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20LIGHT%5B%22%E8%BD%BB%E9%87%8F%E8%AF%BB%E6%95%B0%EF%BC%9A%E6%8E%A2%E9%92%88%20%2F%20%E7%89%B9%E5%BE%81%E8%AF%BB%E6%95%B0%22%5D%0A%20%20LIGHT%20--%3E%7C%E4%BD%8E%E4%BA%8E%E9%98%88%E5%80%BC%7C%20PASS%5B%22%E6%94%BE%E8%A1%8C%22%5D%0A%20%20LIGHT%20--%3E%7C%E5%8F%AF%E7%96%91%7C%20HEAVY%5B%22%E9%87%8D%E5%88%86%E6%9E%90%EF%BC%9A%E5%A4%9A%E6%8E%A2%E9%92%88%E6%8A%95%E7%A5%A8%20%2F%20%E5%AD%97%E5%85%B8%E8%AF%BB%E6%95%B0%22%5D%0A%20%20HEAVY%20--%3E%7C%E4%BB%8D%E5%8F%AF%E7%96%91%7C%20OFF%5B%22%E6%8A%BD%E6%A0%B7%E7%A6%BB%E7%BA%BF%EF%BC%9A%E5%BD%92%E5%9B%A0%E5%9B%BE%E6%B7%B1%E6%9F%A5%22%5D%0A%20%20HEAVY%20--%3E%7C%E6%8A%95%E7%A5%A8%E9%80%9A%E8%BF%87%7C%20PASS%0A%20%20OFF%20--%3E%20ALERT%5B%22%E5%91%8A%E8%AD%A6%EF%BC%9A%E8%AF%BB%E6%95%B0%20%2B%20%E6%BF%80%E6%B4%BB%E8%AF%81%E6%8D%AE%20%2B%20%E8%BD%AC%E5%90%91%E8%AE%B0%E5%BD%95%22%5D%0A%20%20ALERT%20--%3E%20HUMAN%5B%22%E4%BA%BA%E5%AE%A1%E4%B8%8E%E5%A4%84%E7%BD%AE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"监控的赌注是「难藏」：欺骗要被执行，计划至少要在残差流里走一遍，而执行路径上的读数难以全程伪装。这是一阶成立——对抗适应后模型可以学会在探针可读的子空间之外表达同一内容，所以探针要定期重验、坐标要随分布更新，第 2 课的换域重测在这里变成例行运维。",-1)),(A(),n(l,null,{default:a(()=>[r(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACT%5B%22%E6%A8%A1%E5%9E%8B%E6%89%A7%E8%A1%8C%E6%AC%BA%E9%AA%97%E8%AE%A1%E5%88%92%22%5D%20--%3E%20RES%5B%22%E8%AE%A1%E5%88%92%E5%86%85%E5%AE%B9%E7%BB%8F%E8%BF%87%E6%AE%8B%E5%B7%AE%E6%B5%81%22%5D%0A%20%20RES%20--%3E%20READ%5B%22%E6%8E%A2%E9%92%88%20%2F%20%E7%89%B9%E5%BE%81%E8%AF%BB%E6%95%B0%E6%8D%95%E8%8E%B7%22%5D%0A%20%20READ%20--%3E%20REP%5B%22%E5%91%8A%E8%AD%A6%EF%BC%9A%E8%AF%BB%E6%95%B0%E5%8A%A0%E8%AF%81%E6%8D%AE%E9%93%BE%22%5D%0A%20%20ADAPT%5B%22%E5%AF%B9%E6%8A%97%E9%80%82%E5%BA%94%EF%BC%9A%E5%AD%A6%E4%BC%9A%E7%BB%95%E5%BC%80%E5%8F%AF%E8%AF%BB%E5%AD%90%E7%A9%BA%E9%97%B4%22%5D%20--%3E%20MISS%5B%22%E5%90%8C%E6%97%8F%E5%86%85%E5%AE%B9%E6%94%B9%E8%B5%B0%E6%8E%A2%E9%92%88%E7%9C%8B%E4%B8%8D%E8%A7%81%E7%9A%84%E6%96%B9%E5%90%91%22%5D%0A%20%20MISS%20--%3E%20FAIL%5B%22%E8%AF%BB%E6%95%B0%E6%BC%8F%E6%A3%80%22%5D%0A%20%20FAIL%20--%3E%20UPD%5B%22%E4%BE%8B%E8%A1%8C%E8%BF%90%E7%BB%B4%EF%BC%9A%E6%8D%A2%E5%9F%9F%E9%87%8D%E9%AA%8C%E3%80%81%E6%9B%B4%E6%96%B0%E5%9D%90%E6%A0%87%22%5D%0A%20%20UPD%20--%3E%20READ%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p><span class="marginnote">这张图回答的是「赌注为什么会赢、又为什么会输」：欺骗要被执行，执行就要在残差流里留下痕迹，这是监控一阶成立的原因；但模型也可能学会把同样的内容换到探针读不到的子空间去表达，于是读数衰减，需要换域重验来追。监控不是装好就完的设备，而是要跟着分布持续校准的仪表。</span></p><p>读数的语义稳定性也要分场合。「欺骗特征激活了」的意思是这次前向经过了与训练时欺骗样本同族的表征方向，不是「模型有欺骗意图」——<a href="/llm/circuit-tracing">电路追踪课</a>划下的边界原样适用：内部故事是可证伪假设，处置要靠人审与行为复核。监控与对齐训练的关系也是单向的：它是检测器，找到的问题交回训练与评测修，自己不治疗原因。</p><p><span class="marginnote">误报率的账：\\(10^{-3}\\) 的误报率在日均 \\(10^7\\) 请求上是一万条告警，\\(10^{-4}\\) 也还有一千条——都超出任何人审组的吞吐。这就是阈值必须从「每天可审条数」倒推的原因：先保精度，召回的缺口交给分层里的重分析与离线深查去补。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>白盒前提：监控要求权重在手，API 模型只能做行为侧的降级版。误报有社会成本，把用户正常请求打成「欺骗」会同时伤体验与信任，处置流程要分级。漏报无法排除：字典没收录的欺骗形态、探针训练分布外的欺骗、以及学会了绕开可读子空间的模型，都在监控视野之外——所以监控只是纵深防御的一层，不是「模型无害」的证据。最后，本课只讨论对自己模型部署监控；把它描述成对第三方模型的检测能力，超出了现有证据。</p><p><span class="marginnote">「纵深防御的一层」是安全工程的常用说法：没有任何单项措施能保证万无一失，就把多层相互独立的防线叠起来——行为评测、激活监控、红队测试、能力限制——让漏过一层的风险被下一层兜住。所以阴性读数的含义是「这层防线没报警」，不是「模型无害」：就像一张阴性化验单不能证明没病。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>监控的主目标是规约博弈三格中的欺骗性对齐；行为与内部读数在此分叉。</li><li>分层架构：全流量轻读数、可疑流量重分析、尾部离线深查；告警必须带证据链。</li><li>阈值从运营吞吐倒推：先保精度，召回由分层补。</li><li>「欺骗方向激活」是表征证据，不是意图判决；探针要例行换域重验。</li><li>出处：Zou et al., 2023 的读写框架；Lindsey et al., 2025（<em>On the Biology of a Large Language Model</em>）的内部追踪案例。</li></ul>',8))])}const u=o(d,[["render",D]]);export{f as __pageData,u as default};
